### FUNCION: initializeGrid
```js
function initializeGrid() {
    const container = document.getElementById('grid-area');
    container.innerHTML = ''; // Clear existing content

    for (let r = 1; r <= ROWS; r++) {
        // Create the row wrapper for the current row number and cells
        const spreadsheetRow = document.createElement('div');
        spreadsheetRow.className = 'spreadsheet-row';
        spreadsheetRow.setAttribute('data-row', r);

        // 1. Row Label (Number)
        const rowLabelDiv = document.createElement('div');
        rowLabelDiv.className = 'row-label';
        rowLabelDiv.textContent = r;
        rowLabelDiv.setAttribute('data-row', r);
        rowLabelDiv.addEventListener('click', handleRowNumberClick);

        // 2. Cell Grid Container (A to J)
        const cellGridDiv = document.createElement('div');
        cellGridDiv.className = 'cell-grid';
        cellGridDiv.setAttribute('data-row', r);

        for (let c = 0; c < COLS; c++) {
            const colLetter = getColumnLetter(c + 1);
            const cellDiv = document.createElement('div');
            cellDiv.className = 'cell';
            cellDiv.setAttribute('data-col', colLetter);
            cellDiv.setAttribute('data-row', r);
            cellDiv.contentEditable = 'false'; // Initially non-editable
            cellDiv.addEventListener('click', handleCellClick);

            // Add placeholder content or initial value if needed
            cellGridDiv.appendChild(cellDiv);
        }

        spreadsheetRow.appendChild(rowLabelDiv);
        spreadsheetRow.appendChild(cellGridDiv);
        container.appendChild(spreadsheetRow);
    }
}
