function clearRow() {
    if (!selectedRow) return;

    const affectedCells = document.querySelectorAll(`.spreadsheet-cell[data-row="${selectedRow}"]`);
    let coordsToUpdate = new Set();

    affectedCells.forEach(cell => {
        // 1. Clear content and reset editable state/background color
        cell.textContent = '';
        cell.removeAttribute('contenteditable');
        cell.style.backgroundColor = ''; // Reset background color to default

        const coord = cell.dataset.coord;
        if (coord) {
            coordsToUpdate.add(coord);
        }
    });

    // 2. Update the data model for all affected cells
    coordsToUpdate.forEach(coord => {
        spreadsheetData[coord].value = ''; // Clear value in state
        spreadsheetData[coord].color = null; // Reset color in state
    });

    saveState();
}
