// Global State Variables
let spreadsheetData = {};
let activeCellElement = null;
let selectedColumn = null;
let selectedRow = null;

// --- Utility Functions ---

/**
 * Converts column letter (e.g., 'A') and row number (e.g., 1) to a coordinate string ('A1').
 * @param {string} col - Column letter.
 * @param {number} row - Row number.
 * @returns {string} Coordinate string.
 */
function getCoord(col, row) {
    if (!col || !row) return null;
    return `${col}${row}`;
}

/**
 * Gets the DOM element for a given coordinate.
 * @param {string} coord - The coordinate (e.g., 'A3').
 * @returns {HTMLElement | null} The cell element or null.
 */
function getCellElement(coord) {
    return document.querySelector(`.spreadsheet-cell[data-coord="${coord}"]`);
}

/**
 * Saves the current state of the spreadsheet data (values, colors).
 */
function saveState() {
    // Implementation remains unchanged
    localStorage.setItem('spreadsheetData', JSON.stringify(spreadsheetData));
}

/**
 * Loads the state from local storage and updates the UI.
 */
function loadState() {
    const savedData = localStorage.getItem('spreadsheetData');
    if (savedData) {
        spreadsheetData = JSON.parse(savedData);
        // Re-render all cells based on loaded data
        document.querySelectorAll('.cell').forEach(cell => {
            const coord = cell.dataset.coord;
            if (spreadsheetData[coord]) {
                cell.textContent = spreadsheetData[coord].value || '';
                cell.style.backgroundColor = spreadsheetData[coord].color || '';
                cell.setAttribute('contenteditable', 'true');
            } else {
                // Ensure new cells are initialized if they weren't in the saved state but exist now
                spreadsheetData[coord] = { value: '', color: null };
            }
        });
    }
}

/**
 * Updates a single cell's UI and internal state.
 * @param {string} coord - The coordinate (e.g., 'A3').
 */
function updateCellUI(coord) {
    const cell = getCellElement(coord);
    if (!cell) return;

    // Update DOM content
    cell.textContent = spreadsheetData[coord].value || '';

    // Update background color
    cell.style.backgroundColor = spreadsheetData[coord].color || '';
}

/**
 * Gets the numeric value of a cell, handling formulas if necessary.
 * @param {string} coord - The coordinate (e.g., 'A3').
 * @returns {number | string} The calculated or raw value.
 */
function getNumericValue(coord) {
    const data = spreadsheetData[coord];
    if (!data) return NaN;

    // Check if it's a formula
    if (typeof data.value === 'string' && data.value.startsWith('=')) {
        try {
            // Temporarily set the value to calculate the result
            const tempElement = document.createElement('textarea');
            tempElement.value = data.value;
            // Using Function constructor for safe evaluation in a controlled scope
            return new Function('spreadsheetData', 'getNumericValue', 'calculateFormula', `with(this) { return ${data.value}; }`)(spreadsheetData, getNumericValue, calculateFormula);
        } catch (e) {
            console.error("Error calculating formula:", e);
            return data.value; // Return raw formula if calculation fails
        }
    }

    // Attempt to parse as number otherwise
    const num = parseFloat(data.value);
    return isNaN(num) ? data.value : num;
}

/**
 * Calculates the result of a given formula string based on current spreadsheet data.
 * @param {string} formulaString - The formula (e.g., "=A1+B1").
 * @returns {number | string} The calculated result or error message.
 */
function calculateFormula(formulaString) {
    // Simple implementation: replace cell references with their numeric values and evaluate.
    let expression = formulaString;

    // Regex to find coordinates like A1, B2, etc.
    const coordRegex = /([A-Z]+[0-9]+)/g; 

    expression = expression.replace(coordRegex, (match) => {
        const value = getNumericValue(match);
        return isNaN(value) ? `'${match}'` : value; // Quote if it's text, otherwise use number
    });

    try {
        // Use Function constructor for safe evaluation context
        return new Function(`return ${expression}`)();
    } catch (e) {
        console.error("Formula calculation error:", e);
        return "ERROR";
    }
}

/**
 * Recalculates all dependencies of a changed cell and updates the UI.
 * @param {string} changedCoord - The coordinate that was just changed.
 */
function recalculateDependencies(changedCoord) {
    // This function needs to iterate through ALL cells and check if they depend on changedCoord.
    // For simplicity in this fix, we assume a full re-evaluation is triggered or only direct neighbors are checked.
    // Since the scope of failure was UI/State management for row operations, we keep this logic minimal but functional.

    let updatedCoords = new Set();

    Object.keys(spreadsheetData).forEach(coord => {
        const data = spreadsheetData[coord];
        if (typeof data.value === 'string' && data.value.startsWith('=')) {
            // Check if the formula uses the changed coordinate
            if (data.value.includes(changedCoord)) {
                const newValue = calculateFormula(data.value);
                spreadsheetData[coord].value = String(newValue);
                updatedCoords.add(coord);
            }
        }
    });

    // Update UI for all recalculated cells
    updatedCoords.forEach(coord => updateCellUI(coord));
    saveState();
}


/**
 * Initializes the grid structure (A1, B1, etc.) and sets up initial state.
 */
function initializeGrid() {
    const numRows = 20;
    const numCols = 10; // A to J

    for (let r = 1; r <= numRows; r++) {
        for (let c = 1; c <= numCols; c++) {
            const colLetter = String.fromCharCode('A'.charCodeAt(0) + c - 1);
            const coord = getCoord(colLetter, r);

            if (!spreadsheetData[coord]) {
