    const target = event.currentTarget;
    if (!target || !target.dataset.coord) return;

    // 1. Select the cell visually and logically
    clearSelection();
    selectCell(target);
    activeCellElement = target;

    // 2. Update state tracking (assuming A is always selected initially for row/col context)
    const coord = target.dataset.coord;
