### FUNCION: initializeGrid
```js
function initializeGrid() {
    const gridArea = document.getElementById('grid-area');
    if (!gridArea) return;

    // Clear existing content before re-initialization
    gridArea.innerHTML = '';

    for (let r = 1; r <= MAX_ROWS; r++) {
        // Create the row wrapper element
        const rowWrapper = document.createElement('div');
        rowWrapper.className = 'spreadsheet-row';
        rowWrapper.dataset.rowIndex = r;

        // 1. Row Label (The number)
        const labelDiv = document.createElement('div');
        labelDiv.className = 'row-label';
        labelDiv.textContent = r;
        labelDiv.dataset.row = r;
        labelDiv.addEventListener('click', handleRowNumberClick);

        // 2. Cell Grid Container (A to J)
        const cellGridContainer = document.createElement('div');
        cellGridContainer.className = 'cell-grid';
        cellGridContainer.dataset.row = r;

        for (let c = 0; c < MAX_COLUMNS; c++) {
            const colLetter = getColumnLetter(c);
            const cellDiv = document.createElement('div');
            cellDiv.className = 'cell';
            cellDiv.dataset.col = colLetter;
            cellDiv.dataset.row = r;
            cellDiv.contentEditable = true; // Make it editable on load
            cellDiv.addEventListener('click', handleCellClick);
            cellGridContainer.appendChild(cellDiv);
        }

        // Append label and cell grid to the row wrapper
        rowWrapper.appendChild(labelDiv);
        rowWrapper.appendChild(cellGridContainer);

        gridArea.appendChild(rowWrapper);
    }
}
```

