function handleCellClick(event) {
    const cellElement = event.currentTarget;
    const coord = getCoord(cellElement.dataset.col, cellElement.dataset.row);

    // 1. Select the cell and update UI
    selectCell(cellElement);
    updateCellUI(coord);

    // 2. Focus for immediate editing (R10 requirement)
    if (!event.target.isContentEditable || event.target.contentEditable === 'false') {
        cellElement.focus();
    }

    // 3. Update controls and state
    updateControls(coord);
    saveState();
}
