function handleCellInput(event) {
    const cellElement = event.currentTarget;
    const coord = getCoord(cellElement.dataset.col, cellElement.dataset.row);
    let value = event.target.innerText;

    // Prevent saving empty strings if the user deletes content entirely
    if (value === '') {
        value = ''; // Keep it as an empty string for state management
    }

    // Update internal model and UI
    updateCellModel(coord, value);
    updateCellUI(coord);

    // Recalculate dependencies if the input is a number or formula
    if (!isNaN(parseFloat(value)) || (typeof value === 'string' && (value.startsWith('=') || /^[a-zA-Z]+\(...)/.test(value)))) {
        recalculateDependencies(coord);
    }

    // Update controls and state
    updateControls(coord);
    saveState();
}
